    const h = this.cell.height;
    const px = e.deltaMode === 1 ? e.deltaY * h : e.deltaMode === 2 ? e.deltaY * h * this.term.rows : e.deltaY;
    this.wheelRest += px / h;
    const lines = Math.trunc(this.wheelRest);
    this.wheelRest -= lines;
